import styled from '@emotion/styled';

type KpiOverviewVariation = 'export' | 'innovation' | undefined;

interface StyledKpiOverviewCardContentProps {
  $variation?: KpiOverviewVariation;
}

export const StyledKpiOverviewCardContent = styled('div', {
  shouldForwardProp: (propName) => propName !== '$variation',
})<StyledKpiOverviewCardContentProps>(({ $variation }) => ({
  width: '198px',
  minHeight: '468px',
  display: 'flex',
  flexDirection: 'column',

  '@media (min-width: 1440px)': {
    width: '228px',
  },

  '@media (min-width: 1920px)': {
    width: '264px',
  },

  '.bigNumberContainer': {
    height: 'auto',
  },

  ...($variation === 'export' && {
    width: '312px',
    minHeight: '568px',

    '@media (min-width: 1440px)': {
      width: '312px',
    },

    '@media (min-width: 1920px)': {
      width: '312px',
    },
  }),

  ...($variation === 'innovation' && {
    boxSizing: 'border-box',
    width: '250px',
    minWidth: 0,
    maxHeight: '695px',

    '@media (min-width: 1440px)': {
      width: '285px',
    },

    '@media (min-width: 1920px)': {
      width: '336px',
    },
  }),
}));

export const StyledNoticeMessageContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  flex: 1,
  minHeight: 0,
  width: '100%',
  padding: 0,
});

export const StyledNoticeHeaderBlock = styled.div({
  flexShrink: 0,
  padding: '16px 16px 0',
});

export const StyledNoticeDivider = styled.div({
  flexShrink: 0,
  height: '1px',
  width: '100%',
  marginTop: '12px',
  backgroundColor: '#14141414',
});

export const StyledNoticeBodyBlock = styled.div({
  flex: 1,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  minHeight: '420px',
  padding: '12px 16px 16px',
});

interface StyledChartContainerProps {
  $hasNoticeMessage?: boolean;
  $variation?: KpiOverviewVariation;
}

export const StyledChartContainer = styled('div', {
  shouldForwardProp: (propName) =>
    !['$hasNoticeMessage', '$variation'].includes(propName),
})<StyledChartContainerProps>(({ $hasNoticeMessage, $variation }) => ({
  height: '300px',
  maxWidth: '228px',
  display: 'flex',
  marginBottom: '8px',
  borderTop: '1px solid #14141414',

  '@media (min-width: 1440px)': {
    maxWidth: '228px',
  },

  '@media (min-width: 1920px)': {
    maxWidth: '264px',
  },

  ...($hasNoticeMessage && {
    flex: 1,
    minHeight: 0,
    height: 'auto',
    width: '100%',
    maxWidth: '100%',
    justifyContent: 'center',
    alignItems: 'center',
    alignSelf: 'stretch',
    marginBottom: 0,
    borderTop: 'none',
  }),

  ...($variation === 'export' && {
    height: '380px',
    maxWidth: '312px',

    '@media (min-width: 1440px)': {
      maxWidth: '312px',
    },

    '@media (min-width: 1920px)': {
      maxWidth: '312px',
    },
  }),

  ...($variation === 'innovation' && {
    width: '100%',
    maxWidth: '100%',
    height: '200px',

    '@media (min-width: 1440px)': {
      width: '100%',
    },

    '@media (min-width: 1920px)': {
      width: '100%',
    },
  }),

  ...($hasNoticeMessage &&
    $variation === 'export' && {
      minHeight: '320px',
    }),

  ...($hasNoticeMessage &&
    $variation === 'innovation' && {
      minHeight: '200px',
    }),
}));
